import{_ as a,o as t,c as i,a3 as n}from"./chunks/framework.BPaanrMb.js";const p=JSON.parse('{"title":"Localization, coordinate frames, and calibration","description":"Verify coordinate frames, units, extrinsics, and localization timing before tuning algorithm parameters.","frontmatter":{"title":"Localization, coordinate frames, and calibration","description":"Verify coordinate frames, units, extrinsics, and localization timing before tuning algorithm parameters.","content_type":"knowledge","status":"design guidance","scope":"localization and multi-sensor coordinate handling","keywords":["localization","frame_id","extrinsic calibration","coordinate transform"],"evidence_ids":[]},"headers":[],"relativePath":"en/knowledge/localization-and-calibration.md","filePath":"en/knowledge/localization-and-calibration.md","lastUpdated":1794551845000}'),o={name:"en/knowledge/localization-and-calibration.md"};function r(s,e,d,l,c,m){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="localization-coordinate-frames-and-calibration" tabindex="-1">Localization, coordinate frames, and calibration <a class="header-anchor" href="#localization-coordinate-frames-and-calibration" aria-label="Permalink to &quot;Localization, coordinate frames, and calibration&quot;">​</a></h1><p><strong>Status:</strong> <code>design guidance</code> · <strong>Core rule:</strong> prove coordinates and calibration before tuning algorithm parameters</p><h2 id="minimum-check-set" tabindex="-1">Minimum check set <a class="header-anchor" href="#minimum-check-set" aria-label="Permalink to &quot;Minimum check set&quot;">​</a></h2><ul><li>Is every message&#39;s <code>frame_id</code>, parent/child relationship, and axis direction explicit?</li><li>Are units for length, angle, and velocity consistent?</li><li>Are extrinsic validity periods, mounting orientation, and transform order recorded?</li><li>Does localization timestamp describe the vehicle state rather than processing completion?</li><li>Are trajectories, maps, perceived objects, and chassis feedback expressed in the same reference frame?</li></ul><h2 id="typical-symptoms-and-hypotheses" tabindex="-1">Typical symptoms and hypotheses <a class="header-anchor" href="#typical-symptoms-and-hypotheses" aria-label="Permalink to &quot;Typical symptoms and hypotheses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>First hypothesis</th><th>Cheap evidence</th></tr></thead><tbody><tr><td>Whole vehicle appears translated</td><td>Extrinsic, initial pose, or map-frame mismatch</td><td>Overlay trajectories and static landmarks</td></tr><tr><td>Turn direction is reversed</td><td>Axis or angle-sign convention error</td><td>Inspect transform matrix and handedness</td></tr><tr><td>Intermittent pose/speed jumps</td><td>Time alignment or localization reset</td><td>Compare state sequence with reset logs</td></tr></tbody></table><p>These are general diagnostics, not proof that WheelOS has validated every vehicle and sensor combination.</p>',7)])])}const f=a(o,[["render",r]]);export{p as __pageData,f as default};
